<!-- Interactive Mobile Device Preview Modal (Overlay for Teacher) -->
<div class="fixed inset-0 bg-on-surface/40 backdrop-blur-sm z-50 hidden items-center justify-center p-space-md" id="modal-mobile-preview">
<div class="bg-surface-container-lowest rounded-2xl shadow-xl w-full max-w-sm overflow-hidden flex flex-col transition-all border-4 border-surface-container-high">
<!-- Phone Bezel Header -->
<div class="bg-inverse-surface text-inverse-on-surface px-space-md py-space-xs flex items-center justify-between">
<span class="font-code-inline text-code-inline">09:41</span>
<div class="h-4 w-20 bg-inverse-surface rounded-full flex items-center justify-center">
<div class="h-2 w-2 rounded-full bg-outline"></div>
</div>
<div class="flex items-center gap-1">
