</button>
</div>
<!-- Phone Body Content -->
<div class="p-space-md flex flex-col gap-space-md bg-surface flex-1">
<div class="flex items-center justify-between">
<span class="font-code-inline text-code-inline px-space-xs py-0.5 rounded bg-primary-fixed text-primary font-bold" id="modal-phone-id">KUIS-HTML-01</span>
<span class="font-body-sm text-body-sm text-outline">Soal 1 dari 4</span>
</div>
<div class="p-space-sm rounded-xl bg-surface-container-lowest shadow-sm">
<p class="font-body-md text-body-md text-on-surface font-medium leading-snug" id="modal-phone-question">
            Tag HTML manakah yang digunakan untuk membuat judul utama paling besar pada halaman web?
          </p>
</div>
<div class="flex flex-col gap-space-xs">
<div class="p-space-sm rounded-xl bg-surface-container-lowest text-on-surface font-body-sm text-body-sm flex items-center gap-space-sm shadow-sm">
<span class="h-6 w-6 rounded-full bg-surface-container flex items-center justify-center font-bold text-outline">A</span>
<span>&lt;head&gt;</span>
</div>
<div class="p-space-sm rounded-xl bg-tertiary-fixed text-on-tertiary-fixed font-body-sm text-body-sm flex items-center gap-space-sm shadow-sm font-bold">
<span class="h-6 w-6 rounded-full bg-tertiary text-on-tertiary flex items-center justify-center font-bold">B</span>
<span id="modal-phone-key">&lt;h1&gt; (Kunci Jawaban Guru)</span>
</div>
<div class="p-space-sm rounded-xl bg-surface-container-lowest text-on-surface font-body-sm text-body-sm flex items-center gap-space-sm shadow-sm">
<span class="h-6 w-6 rounded-full bg-surface-container flex items-center justify-center font-bold text-outline">C</span>
<span>&lt;heading&gt;</span>
</div>
</div>
<div class="mt-auto p-space-sm rounded-xl bg-surface-container text-on-surface-variant flex items-center justify-between font-body-sm text-body-sm">
<span>Tingkat Keberhasilan:</span>
<span class="font-bold text-tertiary" id="modal-phone-success">96% Siswa</span>
</div>
</div>
<div class="p-space-sm bg-surface-container-lowest text-center">
<button class="w-full py-space-xs rounded-xl bg-primary text-on-primary font-body-md text-body-md font-semibold" onclick="closeMobilePreview()" type="button">
          Tutup Pratinjau
        </button>
</div>
</div>
</div>
<script>
    // Tab switching behavior
    const tabQuizTrigger = document.getElementById('tab-quiz-trigger');
    const tabLabTrigger = document.getElementById('tab-lab-trigger');
    const tabQuizContent = document.getElementById('tab-quiz-content');
    const tabLabContent = document.getElementById('tab-lab-content');

    tabQuizTrigger.addEventListener('click', () => {
      tabQuizTrigger.className = 'flex-1 sm:flex-initial inline-flex items-center justify-center gap-space-sm px-space-lg py-space-sm rounded-xl font-body-md text-body-md font-semibold transition-all bg-surface-container-lowest text-primary shadow-sm';
      tabLabTrigger.className = 'flex-1 sm:flex-initial inline-flex items-center justify-center gap-space-sm px-space-lg py-space-sm rounded-xl font-body-md text-body-md font-semibold transition-all text-on-surface-variant hover:text-on-surface hover:bg-surface-container';
      tabQuizContent.classList.remove('hidden');
      tabLabContent.classList.add('hidden');
    });

    tabLabTrigger.addEventListener('click', () => {
      tabLabTrigger.className = 'flex-1 sm:flex-initial inline-flex items-center justify-center gap-space-sm px-space-lg py-space-sm rounded-xl font-body-md text-body-md font-semibold transition-all bg-surface-container-lowest text-primary shadow-sm';
      tabQuizTrigger.className = 'flex-1 sm:flex-initial inline-flex items-center justify-center gap-space-sm px-space-lg py-space-sm rounded-xl font-body-md text-body-md font-semibold transition-all text-on-surface-variant hover:text-on-surface hover:bg-surface-container';
      tabLabContent.classList.remove('hidden');
      tabQuizContent.classList.add('hidden');
    });

    // Lab Cases Data Store
    const labCases = {
      1: {
        id: 'LAB-HTML-01',
        title: 'LAB-HTML-01: Lupa Tag Penutup Tombol Kirim',
        desc: 'Siswa diminta memperbaiki kode form pendaftaran berikut di mana tombol "Kirim Data" gagal di-render dengan benar oleh browser karena tag <button> lupa ditutup. Kunci solusi mengharuskan tag penutup </button> diletakkan setelah teks label tombol.',
        codeSoal: `<pre class="m-0 text-outline-variant select-all"><span class="text-secondary-fixed">&lt;form</span> <span class="text-tertiary-fixed">action=</span><span class="text-secondary-container">"/submit"</span><span class="text-secondary-fixed">&gt;</span>\n  <span class="text-secondary-fixed">&lt;label&gt;</span>Nama Lengkap:<span class="text-secondary-fixed">&lt;/label&gt;</span>\n  <span class="text-secondary-fixed">&lt;input</span> <span class="text-tertiary-fixed">type=</span><span class="text-secondary-container">"text"</span> <span class="text-tertiary-fixed">name=</span><span class="text-secondary-container">"nama"</span><span class="text-secondary-fixed">&gt;</span>\n  <span class="bg-error/30 text-error-container px-1 rounded">&lt;button type="submit"&gt;Kirim Data</span> <span class="text-error font-bold">&lt;!-- BUG: Tag penutup tidak ada --&gt;</span>\n<span class="text-secondary-fixed">&lt;/form&gt;</span></pre>`,
        codeKunci: `<pre class="m-0 text-outline-variant select-all"><span class="text-secondary-fixed">&lt;form</span> <span class="text-tertiary-fixed">action=</span><span class="text-secondary-container">"/submit"</span><span class="text-secondary-fixed">&gt;</span>\n  <span class="text-secondary-fixed">&lt;label&gt;</span>Nama Lengkap:<span class="text-secondary-fixed">&lt;/label&gt;</span>\n  <span class="text-secondary-fixed">&lt;input</span> <span class="text-tertiary-fixed">type=</span><span class="text-secondary-container">"text"</span> <span class="text-tertiary-fixed">name=</span><span class="text-secondary-container">"nama"</span><span class="text-secondary-fixed">&gt;</span>\n  <span class="bg-tertiary/20 text-tertiary-fixed px-1 rounded">&lt;button type="submit"&gt;Kirim Data&lt;/button&gt;</span>\n<span class="text-secondary-fixed">&lt;/form&gt;</span></pre>`,
        diagnostic: 'Menemukan token tidak seimbang pada baris 4: Unclosed tag <button>. Kunci jawaban memulihkan pohon parsing DOM secara valid.'
      },
      2: {
        id: 'LAB-HTML-02',
        title: 'LAB-HTML-02: Link Navigasi Rusak (Atribut href Hilang)',
        desc: 'Tag jangkar navigasi <a> disajikan tanpa atribut href tujuan. Siswa harus menambahkan atribut href="/tentang" agar tautan dapat diklik dan berfungsi sesuai standar HTML5.',
        codeSoal: `<pre class="m-0 text-outline-variant select-all"><span class="text-secondary-fixed">&lt;nav&gt;</span>\n  <span class="bg-error/30 text-error-container px-1 rounded">&lt;a&gt;Tentang Kami&lt;/a&gt;</span> <span class="text-error font-bold">&lt;!-- BUG: href tidak ada --&gt;</span>\n  <span class="text-secondary-fixed">&lt;a</span> <span class="text-tertiary-fixed">href=</span><span class="text-secondary-container">"/kontak"</span><span class="text-secondary-fixed">&gt;Kontak&lt;/a&gt;</span>\n<span class="text-secondary-fixed">&lt;/nav&gt;</span></pre>`,
        codeKunci: `<pre class="m-0 text-outline-variant select-all"><span class="text-secondary-fixed">&lt;nav&gt;</span>\n  <span class="bg-tertiary/20 text-tertiary-fixed px-1 rounded">&lt;a href="/tentang"&gt;Tentang Kami&lt;/a&gt;</span>\n  <span class="text-secondary-fixed">&lt;a</span> <span class="text-tertiary-fixed">href=</span><span class="text-secondary-container">"/kontak"</span><span class="text-secondary-fixed">&gt;Kontak&lt;/a&gt;</span>\n<span class="text-secondary-fixed">&lt;/nav&gt;</span></pre>`,
        diagnostic: 'Missing mandatory anchor attribute: Node <a> requires href target for interactive compliance.'
      },
      3: {
        id: 'LAB-HTML-03',
        title: 'LAB-HTML-03: Hierarki Judul Terbalik (Tag h1 dan p Tertukar)',
        desc: 'Struktur kode artikel menukar peran judul utama dengan paragraf biasa. Siswa harus merestrukturisasi urutan semantic headings agar dokumen memiliki struktur outline halaman yang benar.',
        codeSoal: `<pre class="m-0 text-outline-variant select-all"><span class="text-secondary-fixed">&lt;article&gt;</span>\n  <span class="bg-error/30 text-error-container px-1 rounded">&lt;p&gt;Pengenalan Web Modern&lt;/p&gt;</span> <span class="text-error font-bold">&lt;!-- Seharusnya Judul Utama --&gt;</span>\n  <span class="text-secondary-fixed">&lt;h1&gt;HTML adalah bahasa markup standar.&lt;/h1&gt;</span>\n<span class="text-secondary-fixed">&lt;/article&gt;</span></pre>`,
        codeKunci: `<pre class="m-0 text-outline-variant select-all"><span class="text-secondary-fixed">&lt;article&gt;</span>\n  <span class="bg-tertiary/20 text-tertiary-fixed px-1 rounded">&lt;h1&gt;Pengenalan Web Modern&lt;/h1&gt;</span>\n  <span class="text-secondary-fixed">&lt;p&gt;HTML adalah bahasa markup standar.&lt;/p&gt;</span>\n<span class="text-secondary-fixed">&lt;/article&gt;</span></pre>`,
        diagnostic: 'Heading hierarchy violation detected: <h1> subordinated underneath standard paragraph node.'
      }
    };

    function selectLabCase(index) {
      [1, 2, 3].forEach(i => {
        const card = document.getElementById('lab-card-' + i);
        if (i === index) {
          card.classList.add('ring-2', 'ring-primary');
        } else {
          card.classList.remove('ring-2', 'ring-primary');
        }
      });

      const selected = labCases[index];
      document.getElementById('inspector-case-title').innerText = selected.title;
      document.getElementById('inspector-case-desc').innerText = selected.desc;
      document.getElementById('code-soal-display').innerHTML = selected.codeSoal;
      document.getElementById('code-kunci-display').innerHTML = selected.codeKunci;
      document.getElementById('diagnostic-message').innerText = selected.diagnostic;
      document.getElementById('diagnostic-status').innerText = 'STATUS: SINKRONISASI COCOK 100%';
      document.getElementById('diagnostic-status').className = 'text-tertiary-fixed font-bold';
    }

    function runInspectorSimulation() {
      const status = document.getElementById('diagnostic-status');
      status.innerText = 'MEMVERIFIKASI TEST HARNESS...';
      status.className = 'text-secondary-fixed font-bold animate-pulse';
      setTimeout(() => {
        status.innerText = 'STATUS: VALIDATOR PASS (0 Syntax Errors)';
        status.className = 'text-tertiary-fixed font-bold';
      }, 700);
    }

    // Mobile Quiz Preview Modal logic
    function previewMobileQuiz(id, question, key, rate) {
      document.getElementById('modal-phone-id').innerText = id;
      document.getElementById('modal-phone-question').innerText = question;
      document.getElementById('modal-phone-key').innerText = key + ' (Kunci Benar)';
      document.getElementById('modal-phone-success').innerText = rate + ' Siswa';
      const modal = document.getElementById('modal-mobile-preview');
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }

    function closeMobilePreview() {
      const modal = document.getElementById('modal-mobile-preview');
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }

    // Top action triggers
    document.getElementById('btn-add-quiz').addEventListener('click', () => {
      tabQuizTrigger.click();
      window.scrollTo({ top: 300, behavior: 'smooth' });
    });
    document.getElementById('btn-add-lab').addEventListener('click', () => {
      tabLabTrigger.click();
      window.scrollTo({ top: 300, behavior: 'smooth' });
    });
  </script>
</div></main></div></body></html>